<?php
declare(strict_types=1);require dirname(__DIR__).'/lib/bootstrap.php';require dirname(__DIR__).'/lib/admin.php';require dirname(__DIR__).'/lib/analytics.php';require dirname(__DIR__).'/lib/repository.php';require dirname(__DIR__).'/lib/view.php';$pdo=db();$f=['q'=>trim((string)($_GET['q']??'')),'min_price'=>(string)($_GET['min_price']??''),'max_price'=>(string)($_GET['max_price']??''),'min_review'=>(string)($_GET['min_review']??''),'free_shipping'=>isset($_GET['free_shipping'])?1:0,'sort'=>(string)($_GET['sort']??'popular'),'category'=>(int)($_GET['category']??0),'shop'=>(string)($_GET['shop']??'')];$page=max(1,(int)($_GET['page']??1));$items=search_items($pdo,$f,30,($page-1)*30);$cats=categories($pdo);public_header($pdo,'商品一覧・検索');?><h1>商品一覧・検索</h1><form class="searchbox"><input name="q" value="<?=h($f['q'])?>" placeholder="商品名・ショップ名"><select name="category"><option value="0">すべてのカテゴリ</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>" <?=$f['category']==(int)$c['id']?'selected':''?>><?=h((string)$c['name'])?></option><?php endforeach?></select><input type="number" name="min_price" value="<?=h($f['min_price'])?>" placeholder="最低価格"><input type="number" name="max_price" value="<?=h($f['max_price'])?>" placeholder="最高価格"><select name="min_review"><option value="">評価指定なし</option><option value="4">★4以上</option><option value="4.5">★4.5以上</option></select><select name="sort"><option value="popular">PinkClub人気</option><option value="new">新着</option><option value="reviews">レビュー件数</option><option value="review">高評価</option><option value="price_asc">価格が安い順</option><option value="price_desc">価格が高い順</option></select><label><input type="checkbox" name="free_shipping" value="1" <?=$f['free_shipping']?'checked':''?>> 送料無料</label><button>検索</button></form><section class="section"><div class="grid"><?php foreach($items as $item)item_card($item);?></div><div class="pagination"><?php if($page>1):?><a href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">← 前へ</a><?php endif?><?php if(count($items)===30):?><a href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">次へ →</a><?php endif?></div></section><?php render_analytics_beacon();public_footer();
